// frontend/src/lib/outbox.js — Round 6 rebuild plan, Phase 5.
// The unified offline outbox: a generic event queue replacing the
// case-submission-only submission_queue (offlineQueue.js, now retired).
// Every queued action is { event_id, type, payload, created_at, attempts,
// status, last_error }. event_id is generated by the caller (syncStore.js)
// and doubles as the server-side idempotency key — for type:'case.submit'
// it's the SAME uuid as case_records.client_id and the X-Event-Id header
// apps/api's idempotency middleware dedupes on, so there is exactly one id
// per logical submission end to end, not three independently-generated ones.
//
// Only 'case.submit' exists as an event type today (doctor actions stay
// online-only per the Round 6 rebuild plan's item 3 decision) — the schema
// is generic so a future offline-capable action can reuse this store
// without another IndexedDB version bump.
//
// SHARED-DEVICE SAFETY: every row carries owner_id — the auth user id of the
// worker who queued it. The PHC tablets these run on are handed between ASHA
// workers, so the drain loop and the dead-letter UI MUST only ever surface a
// row to the same worker who created it. Without this, Worker B logging in
// after Worker A queued a case offline would submit A's patient data under
// B's identity/JWT (getPendingEvents) and see A's patient name/complaint in
// the dead-letter list (getDeadLetters). Both are scoped by owner_id below.
import { getOfflineDB, LEGACY_RECOVERY_STATUS, CORRUPT_KEY_REASON } from './offlineDB'

const STORE_NAME = 'outbox'
const MAX_PENDING = 50
const RECOVERY_STATUS = LEGACY_RECOVERY_STATUS
export const OUTBOX_STALE_RETENTION_MS = 7 * 24 * 60 * 60 * 1000

function notifyOutboxChange() {
  window.dispatchEvent(new CustomEvent('offline-queue-changed'))
}

// ── Outbox payload encryption for shared-tablet PHI isolation (ADR §47) ──
// Persists non-extractable AES-256-GCM CryptoKey handles directly in IndexedDB v5
// store 'device_keystore', keyed by outbox_aes_gcm_${effectiveOwner}.
// Includes migration bridge from volatile sessionStorage and AAD cryptographic binding.

const _inflightKeyPromises = new Map()

export function buildAad(ownerId, eventId) {
  const aadString = `vn:v2:${ownerId || 'anon'}:${eventId || 'none'}`
  return new TextEncoder().encode(aadString)
}

export async function getOwnerOutboxKey(ownerId) {
  const effectiveOwner = ownerId || 'anon'
  const keyId = `outbox_aes_gcm_${effectiveOwner}`
  if (_inflightKeyPromises.has(keyId)) {
    return _inflightKeyPromises.get(keyId)
  }
  const promise = _resolveOwnerOutboxKey(keyId)
  _inflightKeyPromises.set(keyId, promise)
  try {
    return await promise
  } finally {
    _inflightKeyPromises.delete(keyId)
  }
}

async function _resolveOwnerOutboxKey(keyId) {
  const db = await getOfflineDB()

  // BUG-07: Step 1: Consult IndexedDB device_keystore FIRST
  const record = await db.get('device_keystore', keyId)
  if (record && record.key) {
    return record.key
  }

  // BUG-07: Step 2: Migration Bridge if no IDB key exists
  if (typeof sessionStorage !== 'undefined') {
    const legacySessionKey = sessionStorage.getItem('vn_outbox_key')
    if (legacySessionKey) {
      try {
        const raw = Uint8Array.from(atob(legacySessionKey), (c) => c.charCodeAt(0))
        const importedKey = await crypto.subtle.importKey(
          'raw',
          raw,
          { name: 'AES-GCM', length: 256 },
          false,
          ['encrypt', 'decrypt']
        )
        await db.put('device_keystore', {
          key_id: keyId,
          key: importedKey,
          migrated_from_session: true,
          created_at: new Date().toISOString(),
        })
        sessionStorage.removeItem('vn_outbox_key')
        return importedKey
      } catch (err) {
        console.warn('[VitalNet] Migration of legacy sessionStorage outbox key failed', err)
      }
    }
  }

  // BUG-07: Step 3: Generate persistent non-extractable AES-256-GCM key
  const newKey = await crypto.subtle.generateKey(
    { name: 'AES-GCM', length: 256 },
    false, // extractable: false
    ['encrypt', 'decrypt']
  )

  try {
    await db.put('device_keystore', {
      key_id: keyId,
      key: newKey,
      created_at: new Date().toISOString(),
    })
  } catch (err) {
    console.warn('[VitalNet] Failed saving key to device_keystore', err)
    throw err
  }

  return newKey
}

export async function encryptOutboxPayload(payload, ownerId, eventId) {
  try {
    const key = await getOwnerOutboxKey(ownerId)
    const iv = crypto.getRandomValues(new Uint8Array(12))
    const aad = buildAad(ownerId, eventId)
    const encoded = new TextEncoder().encode(JSON.stringify(payload))
    const ct = await crypto.subtle.encrypt(
      { name: 'AES-GCM', iv, additionalData: aad },
      key,
      encoded
    )
    return {
      _encrypted: true,
      _v: 2,
      iv: Array.from(iv),
      ct: Array.from(new Uint8Array(ct)),
    }
  } catch (err) {
    console.error('[VitalNet] Outbox encryption failed; refusing plaintext fallback', err)
    throw new Error(`Outbox encryption failed: ${err?.message || err}`)
  }
}

export async function decryptOutboxPayload(payload, ownerId, eventId) {
  if (!payload || !payload._encrypted) return payload
  try {
    const key = await getOwnerOutboxKey(ownerId)
    const iv = new Uint8Array(payload.iv)
    const ct = new Uint8Array(payload.ct)

    // v2: decrypt with AAD binding
    if (payload._v === 2) {
      const aad = buildAad(ownerId, eventId)
      const decrypted = await crypto.subtle.decrypt(
        { name: 'AES-GCM', iv, additionalData: aad },
        key,
        ct
      )
      return JSON.parse(new TextDecoder().decode(decrypted))
    }

    // Legacy fallback without AAD
    const decrypted = await crypto.subtle.decrypt(
      { name: 'AES-GCM', iv },
      key,
      ct
    )
    return JSON.parse(new TextDecoder().decode(decrypted))
  } catch (err) {
    console.warn('[VitalNet] Outbox payload decryption failed', err)
    return null
  }
}

/**
 * Queue an event for later sync. Captures performance.now() monotonic offset
 * to eliminate clock rollbacks/skew, encrypts payload with AAD binding, and
 * registers background sync.
 */
export async function enqueue(eventId, type, payload, ownerId) {
  const pendingCount = await getPendingCount()
  if (pendingCount >= MAX_PENDING) {
    console.warn(`[VitalNet] Offline outbox is full (${MAX_PENDING} pending items). Cannot queue more.`)
    throw new Error(`Offline queue is full (${MAX_PENDING} items). Please sync before submitting more cases.`)
  }

  const encryptedPayload = await encryptOutboxPayload(payload, ownerId, eventId)
  const db = await getOfflineDB()
  const monotonicMs = typeof performance !== 'undefined' ? Math.round(performance.now()) : Date.now()
  const timeOriginMs = (typeof performance !== 'undefined' && typeof performance.timeOrigin === 'number') ? performance.timeOrigin : null

  await db.put(STORE_NAME, {
    event_id: eventId,
    owner_id: ownerId ?? null,
    type,
    payload: encryptedPayload,
    created_at: new Date().toISOString(),
    intake_monotonic_ms: monotonicMs,
    enqueued_time_origin: timeOriginMs,
    attempts: 0,
    status: 'pending',
    last_error: null,
  })

  // Register ServiceWorker Background Sync (vitalnet-outbox-sync) if available
  if (typeof navigator !== 'undefined' && 'serviceWorker' in navigator && typeof window !== 'undefined' && 'SyncManager' in window) {
    navigator.serviceWorker.ready
      .then((reg) => reg.sync?.register?.('vitalnet-outbox-sync'))
      .catch(() => {})
  }

  notifyOutboxChange()
}

/**
 * Queue an offline consent revocation tombstone event (ADR §55).
 */
export async function enqueueConsentRevocation(clientId, ownerId, reason = 'patient_withdrew_consent_offline') {
  const db = await getOfflineDB()
  // BUG-08: Coalesce local case.submit items when revoking consent
  const all = await db.getAll(STORE_NAME)
  for (const item of all) {
    if (
      (item.event_id === clientId || item.payload?.client_id === clientId) &&
      item.type === 'case.submit'
    ) {
      await db.delete(STORE_NAME, item.event_id)
    }
  }

  const eventId = typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : `revoke-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`
  await enqueue(
    eventId,
    'case.revoke_consent',
    {
      client_id: clientId,
      reason,
      revoked_at: new Date().toISOString(),
    },
    ownerId
  )
  return eventId
}

export async function dequeue(eventId) {
  const db = await getOfflineDB()
  await db.delete(STORE_NAME, eventId)
  notifyOutboxChange()
}

/**
 * Pending events owned by `ownerId`, oldest first — the FIFO drain order
 * processQueue() uses. Scoped by owner so a worker never drains a case another
 * worker queued on the same device.
 * Enforces quarantine self-healing: if an encrypted row fails decryption,
 * it transitions to 'recovery_required' with CORRUPT_KEY_REASON so it no longer
 * counts toward MAX_PENDING = 50.
 */
export async function getPendingEvents(ownerId) {
  if (!ownerId) return []
  const db = await getOfflineDB()
  const all = await db.getAllFromIndex(STORE_NAME, 'created_at')
  const owned = all.filter((e) => e.status === 'pending' && e.owner_id === ownerId)
  const decrypted = []

  for (const item of owned) {
    const plain = await decryptOutboxPayload(item.payload, item.owner_id, item.event_id)
    if (plain) {
      decrypted.push({ ...item, payload: plain })
    } else if (item.payload && item.payload._encrypted) {
      // Quarantine self-healing (ADR §47)
      console.warn(`[VitalNet] Quarantining unrecoverable event ${item.event_id} due to key loss.`)
      const tx = db.transaction(STORE_NAME, 'readwrite')
      const row = await tx.store.get(item.event_id)
      if (row && row.status === 'pending') {
        row.status = RECOVERY_STATUS
        row.recovery_reason = CORRUPT_KEY_REASON
        row.last_error = 'Encrypted under a lost legacy session key; requires device cleanup.'
        await tx.store.put(row)
      }
      await tx.done
      notifyOutboxChange()
    }
  }
  return decrypted
}

/**
 * Total pending count across ALL owners. This is a device-level indicator
 * only (the "N pending" badge and the capacity guard) — it exposes no PHI,
 * just a number — so it is intentionally not owner-scoped.
 */
export async function getPendingCount() {
  const db = await getOfflineDB()
  return db.countFromIndex(STORE_NAME, 'status', 'pending')
}

/**
 * Count legacy rows that cannot be safely attributed to a worker. This is an
 * aggregate-only signal: callers must not receive the payload or identifiers.
 */
export async function getRecoveryRequiredCount(ownerId = null) {
  const db = await getOfflineDB()
  const rows = await db.getAllFromIndex(STORE_NAME, 'status', RECOVERY_STATUS)
  if (!ownerId) {
    return rows.filter((r) => r.owner_id == null).length
  }
  return rows.filter((r) => r.owner_id === ownerId || r.owner_id == null).length
}

/**
 * Aggregate count of this worker's pending rows older than the documented
 * review window. The payload is never returned to the caller.
 */
export async function getStalePendingCount(ownerId, now = Date.now()) {
  if (!ownerId) return 0
  const db = await getOfflineDB()
  const all = await db.getAllFromIndex(STORE_NAME, 'status', 'pending')
  return all.filter((row) => (
    row.owner_id === ownerId
    && Number.isFinite(Date.parse(row.created_at))
    && now - Date.parse(row.created_at) >= OUTBOX_STALE_RETENTION_MS
  )).length
}

/**
 * Explicitly purge only this worker's stale pending rows after user review.
 * This is never called automatically and cannot affect another worker's rows.
 */
export async function purgeStalePending(ownerId, now = Date.now()) {
  if (!ownerId) return 0
  const db = await getOfflineDB()
  const all = await db.getAllFromIndex(STORE_NAME, 'status', 'pending')
  let removed = 0
  for (const row of all) {
    if (
      row.owner_id === ownerId
      && Number.isFinite(Date.parse(row.created_at))
      && now - Date.parse(row.created_at) >= OUTBOX_STALE_RETENTION_MS
    ) {
      await db.delete(STORE_NAME, row.event_id)
      removed += 1
    }
  }
  if (removed > 0) notifyOutboxChange()
  return removed
}

/**
 * Permanently purge ownerless legacy recovery records after an explicit
 * device-level confirmation. This never touches pending, dead-lettered, or
 * currently owned rows of other workers (BUG-24).
 */
export async function purgeRecoveryRequired(ownerId = null) {
  if (!ownerId) return 0
  const db = await getOfflineDB()
  const rows = await db.getAllFromIndex(STORE_NAME, 'status', RECOVERY_STATUS)
  let removed = 0
  for (const row of rows) {
    if (row.owner_id === ownerId || row.owner_id == null) {
      await db.delete(STORE_NAME, row.event_id)
      removed += 1
    }
  }
  if (removed > 0) notifyOutboxChange()
  return removed
}

/**
 * A permanent (4xx) failure — surfaced to the UI as a dead-letter list
 * instead of being silently dropped or retried forever.
 */
export async function markDead(eventId, lastError) {
  const db = await getOfflineDB()
  const tx = db.transaction(STORE_NAME, 'readwrite')
  const row = await tx.store.get(eventId)
  if (row) {
    row.status = 'dead'
    row.last_error = lastError
    await tx.store.put(row)
  }
  await tx.done
  notifyOutboxChange()
}

export async function incrementAttempts(eventId) {
  const db = await getOfflineDB()
  const tx = db.transaction(STORE_NAME, 'readwrite')
  const row = await tx.store.get(eventId)
  if (row) {
    row.attempts = (row.attempts || 0) + 1
    await tx.store.put(row)
  }
  await tx.done
}

/**
 * Dead-lettered events owned by `ownerId`. Owner-scoped because these rows
 * carry patient_name/chief_complaint that the dead-letter UI renders — an
 * unscoped list would show one worker another worker's patient PHI on a
 * shared device. Returns [] when ownerId is falsy.
 */
export async function getDeadLetters(ownerId) {
  if (!ownerId) return []
  const db = await getOfflineDB()
  const all = await db.getAllFromIndex(STORE_NAME, 'status', 'dead')
  const owned = all.filter((e) => e.owner_id === ownerId)
  const decrypted = []
  for (const item of owned) {
    const plain = await decryptOutboxPayload(item.payload, item.owner_id, item.event_id)
    decrypted.push({
      ...item,
      payload: plain || { patient_name: '[Encrypted from prior session]', chief_complaint: 'Offline submission' },
    })
  }
  return decrypted
}

export async function getDeadLetterCount(ownerId) {
  const dead = await getDeadLetters(ownerId)
  return dead.length
}

/** Moves a dead-lettered event back to pending so the next drain retries it. */
export async function retryDeadLetter(eventId) {
  const db = await getOfflineDB()
  const tx = db.transaction(STORE_NAME, 'readwrite')
  const row = await tx.store.get(eventId)
  if (row) {
    row.status = 'pending'
    row.last_error = null
    row.attempts = 0
    await tx.store.put(row)
  }
  await tx.done
  notifyOutboxChange()
}

/** Discards a dead-lettered event permanently (worker has reviewed and dismissed it). */
export async function discardDeadLetter(eventId) {
  await dequeue(eventId)
}
